PHOTONIC_EDGE_DIM = 15

# 三关系（*创新* 2，R-GCN Schlichtkrull 2018）
RELATION_OPTICAL = 0  # 光-光（光波导）
RELATION_OPTOELECTRICAL = 1  # 光-电（光电转换）
RELATION_ELECTRICAL = 2  # 电-电（电信号）
NUM_RELATIONS = 3

