            lim = np.sqrt(6.0 / (h + h))
            rgcn_self.append(self._rng.uniform(-lim, lim, size=(h, h)))
            rgcn_basis.append(self._rng.uniform(-lim, lim, size=(b, h, h)))
            rgcn_coeffs.append(self._rng.uniform(-lim, lim, size=(r, b)))
