        if self.hidden_dim < 1:
            raise ValueError(f"hidden_dim 须 ≥1，得到 {self.hidden_dim}")
        if self.n_edge_features != PHOTONIC_EDGE_DIM:
            raise ValueError(
                f"n_edge_features 须为 {PHOTONIC_EDGE_DIM}（15 维光子边特征）"
            )


