def _segment_softmax(scores: np.ndarray, dsts: np.ndarray, n: int) -> np.ndarray:
    """按 dst 节点分组的 softmax（数值稳定，GAT 归一化用）。

    公式: α_ij = exp(e_ij) / Σ_{k∈N(i)} exp(e_ik)  (Veličković 2018)
    """
    max_per_node = np.full(n, -np.inf)
